mapper.select:
SELECT p.id, p.spu_code, p.name, p.alias, p.category_id, p.description, p.status, p.version, p.deleted, p.created_at, p.updated_at, p.created_by, p.updated_by FROM product_spu p WHERE p.deleted = FALSE
AND ( p.spu_code ILIKE CONCAT('%', #{query.keyword}, '%') OR p.name ILIKE CONCAT('%', #{query.keyword}, '%') OR p.alias ILIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM product_sku s WHERE s.spu_id = p.id AND s.deleted = FALSE AND (s.sku_code ILIKE CONCAT('%', #{query.keyword}, '%') OR s.barcode ILIKE CONCAT('%', #{query.keyword}, '%')) ) )
AND p.category_id = #{query.categoryId}
AND p.status = #{query.spuStatus}
AND EXISTS ( SELECT 1 FROM product_sku sf WHERE sf.spu_id = p.id AND sf.deleted = FALSE
AND sf.status = #{query.skuStatus}
AND sf.product_type = #{query.productType}
)
ORDER BY p.updated_at DESC, p.id DESC
